import os, json
from pathlib import Path
print('cwd:', os.getcwd())
memory = Path('../memory/global_mem.txt')
if memory.exists():
    print('memory:', memory.read_text())
p = Path.home() / 'Downloads'
print('downloads:', p)
items = []
folders = 0
errors = []
try:
    with os.scandir(p) as entries:
        for entry in entries:
            try:
                if entry.is_file(follow_symlinks=False):
                    size = entry.stat(follow_symlinks=False).st_size
                    if size > 1_000_000_000:
                        items.append({'path': entry.path, 'bytes': size, 'GB': round(size / 1_000_000_000, 2)})
                elif entry.is_dir(follow_symlinks=False):
                    folders += 1
            except OSError as e:
                errors.append(str(e))
    print(json.dumps({'files': sorted(items, key=lambda x: -x['bytes']), 'subfolder_count_not_searched': folders, 'errors': errors}, ensure_ascii=False, indent=2))
except OSError as e:
    print(type(e).__name__ + ': ' + str(e))

