import runpy
from pathlib import Path
from zipfile import ZipFile
import xml.etree.ElementTree as ET
runpy.run_path('create_hotel_template.py')
p=Path('酒店开业前资料收集模板.xlsx')
ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
with ZipFile(p) as z:
 for name in z.namelist():
  if name.startswith('xl/worksheets/'):
   root=ET.fromstring(z.read(name))
   headers=root.findall('.//s:row[@r="4"]/s:c',ns)
   assert len(headers)>=2
   for row in root.findall('.//s:sheetData/s:row',ns):
    if int(row.attrib['r'])>=5:
     assert len(row.findall('s:c',ns))==len(headers),(name,row.attrib)
   for dv in root.findall('.//s:dataValidation',ns):
    assert len(dv.find('s:formula1',ns).text)<255
 print('PASS: all XML parsed; ZIP integrity, header/row alignment, validation lengths checked.')
print('FINAL',p.resolve())

