from pathlib import Path
import pdfplumber
root=Path.home()/'Downloads'
for p in sorted(root.glob('*'), key=lambda p:p.name):
 if not p.is_file() or p.suffix.lower()!='.pdf':continue
 data=p.read_bytes()
 print('\nFILE',p.name)
 if data.startswith(b'%PDF-'):
  try:
   with pdfplumber.open(p) as pdf:
    print('PAGES',len(pdf.pages)); print('TEXT', '\n'.join((page.extract_text() or '') for page in pdf.pages[:5])[:6000])
  except Exception as e: print('PDF_ERROR',type(e).__name__,str(e)[:200])
 else:
  try: print('TEXT_CONTAINER',data.decode('utf-8')[:3000])
  except UnicodeDecodeError:print('NON_PDF_BINARY',data[:12].hex())

